'use strict';

// MODULES //

var crypto = require( 'crypto' );
var format = require( '@stdlib/string/format' );

// TODO: Merge this method into main.js


// MAIN //

/**
* Generates HMAC code from a list of frames and key.
*
* @private
* @param {Array<Buffer>} frames - raw frames
* @param {string} scheme - signature scheme
* @param {string} key - signature key
* @throws {TypeError} must provide valid HMAC scheme
* @returns {string} HMAC code
*/
function generateHMAC( frames, scheme, key ) {
	var hash;
	var i;

	// TODO: should we validate everything inside the validator itself?
	try {
		hash = crypto.createHmac( scheme, key );
	} catch ( err ) {
		throw new TypeError( format( 'invalid argument. Must provide a valid HMAC scheme. Value: `%s`.', scheme ) );
	}
	for ( i = 0; i < frames.length; i++ ) {
		hash.update( frames[ i ] );
	}
	return hash.digest( 'hex' );
}


// EXPORTS //

module.exports = generateHMAC;
